        "path": "src/components/ui/Button/button.tsx",
        "content": "import { forwardRef } from \"react\";\nimport type { ButtonProps } from \"./button.types\";\nimport { buttonVariants } from \"./button.styles\";\n\nexport const Button = forwardRef<HTMLButtonElement, ButtonProps>(\n  function Button(\n    {\n      color,\n      variant,\n      size,\n      shape,\n      fullWidth,\n      loading = false,\n      disabled = false,\n      iconLeft,\n      iconRight,\n      children,\n      className,\n      type = \"button\",\n      ...rest\n    },\n    ref,\n  ) {\n    const isDisabled = disabled || loading;\n\n    return (\n      <button\n        ref={ref}\n        type={type}\n        disabled={isDisabled}\n        className={buttonVariants({\n          color,\n          variant,\n          size,\n          shape,\n          fullWidth,\n          disabled: isDisabled,\n          className,\n        })}\n        {...rest}\n      >\n        {loading && <Spinner />}\n        {!loading && iconLeft}\n        {children}\n        {!loading && iconRight}\n      </button>\n    );\n  },\n);\n\nfunction Spinner() {\n  return (\n    <svg\n      width=\"16\"\n      height=\"16\"\n      viewBox=\"0 0 16 16\"\n      fill=\"none\"\n      className=\"animate-spin\"\n    >\n      <circle\n        cx=\"8\"\n        cy=\"8\"\n        r=\"6\"\n        stroke=\"currentColor\"\n        strokeWidth=\"2\"\n        strokeLinecap=\"round\"\n        strokeDasharray=\"28\"\n        strokeDashoffset=\"8\"\n        className=\"opacity-70\"\n      />\n    </svg>\n  );\n}\n",
