        "path": "src/examples/finance/components/FinanceDetailPanel/index.ts",
        "content": "export { FinanceDetailPanel } from \"./finance-detail-panel\";\r\nexport type { FinanceDetailPanelProps } from \"./finance-detail-panel\";\r\n",
        "type": "registry:ui",
        "target": "examples/finance/components/FinanceDetailPanel/index.ts"
